fn is_sorted(arr: &Vec<i32>) -> bool {
    // Iterate through the array, comparing each element with the next
    for i in 0..arr.len() - 1 {
        if arr[i] > arr[i + 1] {
            return false; // Found an element greater than the next one
        }
    }
    true // If we finish the loop without finding any issues, the array is sorted
}